def ensure_monorepo_import_paths() -> Path:
    """Add python_client, service-provider runtime, and image-display lib to sys.path."""
    root = repo_root()
    extras = (
        root,
        root / "python_client" / "src",
        root / "image_display" / "lib",
    )
    for path in extras:
        s = str(path)
        if path.is_dir() and s not in sys.path:
            sys.path.insert(0, s)
    return root
